ee:message.ee:set-payload:
%dw 2.0
output application/xml writeDeclaration= false
ns soapenv http://schemas.xmlsoap.org/soap/envelope/
ns orc http://orchestration.cloud.etb.com.co
---
soapenv#Envelope:{
   soapenv#Header: null,
   soapenv#Body:{
       orc#RunOrchService:{
           orc#OrchInput:{
               orc#OrchRequestHeader:{
                   orc#ExternalId: p('mdm-orchestration-service.vars.externalId'),
                   orc#System: p('mdm-orchestration-service.vars.system')
               },
               orc#OrchRequestBody:{
                   orc#Id: p('mdm-orchestration-service.vars.id'),
                   orc#Version: p('mdm-orchestration-service.vars.version'),
                   orc#Parameters:[
                       {
                         orc#Parameter:{
                                orc#Attribute: p('mdm-orchestration-service.vars.attribute'),
                                orc#Value: p('mdm-orchestration-service.vars.valueProcess')
                         }  
                       }
                   ]
               }
           }
       }
   }
}

%dw 2.0
import * from dw::Runtime
output application/json
var consecutivo = try(() -> payload.Envelope.Body.RunOrchServiceResponse.OrchOutput.OrchResponseBody.XmlData.OrchContext.Consecutivo)
---
if (consecutivo.success == true and !isEmpty(consecutivo.result)) 
	{
    	status: "OK",
    	consecutivo: consecutivo.result
    }
 else{ status: "FAIL"}
